const $=id=>document.getElementById(id),money=cents=>(cents/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
export function createPixCheckout({getPattern,getName,canExport,notify}){
 let admin=false,quote=null,order=null,paid=false,sequence=0,timer=null,busy=false,currentKey='',snapshot='';
 let paypalAccess=null,paypalPaid=false,paypalRate=null;
 const inputNow=()=>{const p=getPattern();return {name:getName(),commands:p.commands.map(c=>[c.x,c.y,c.c]),colors:p.blocks.map(b=>b.color)}};
 const unchanged=()=>JSON.stringify(inputNow())===snapshot;
 const stop=()=>{clearTimeout(timer);timer=null};
 const message=s=>$('pixStatus').textContent=s;
 const request=async(path,data)=>{const response=await fetch('/api/pix/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});let result;try{result=await response.json()}catch{throw Error('O checkout não está disponível neste ambiente. Nenhum pagamento foi gerado.')}if(!response.ok)throw Error(result.error||'Não foi possível concluir. Tente novamente.');return result};
 const storageKey=()=> 'bordai-pix-order-v1:'+(quote?.hash||currentKey);
 const remember=()=>{if(!order)return;const value=JSON.stringify(order);try{localStorage.setItem(storageKey(),value)}catch{try{sessionStorage.setItem(storageKey(),value)}catch{notify('Mantenha esta aba aberta para conservar o acesso ao seu pedido.')}}};
 const adminPanel=document.createElement('section');adminPanel.style.cssText='margin:14px 0;padding:12px;border:1px solid #d9deee;border-radius:10px';adminPanel.innerHTML='<button type="button" id="adminToggle" style="width:100%;padding:10px">Acesso do proprietário</button><div id="adminControls" hidden style="margin-top:10px"><input id="adminEmail" type="email" autocomplete="username" value="cristiano.se.adm@gmail.com" placeholder="E-mail do administrador" style="width:100%;box-sizing:border-box;padding:10px;margin-bottom:8px"><input id="adminPassword" type="password" autocomplete="current-password" placeholder="Senha de administrador" style="width:100%;box-sizing:border-box;padding:10px"><button type="button" id="adminLogin" style="margin-top:8px;padding:10px">Entrar</button><button type="button" id="adminLogout" hidden style="margin-top:8px;padding:10px">Sair</button><p id="adminMessage" aria-live="polite"></p></div>';
 $('pixRestore').parentElement.append(adminPanel);
 const paypalPanel=document.createElement('section');paypalPanel.style.cssText='margin:12px 0;padding:14px;border:1px solid #ccd5e8;border-radius:12px';paypalPanel.innerHTML='<strong>🌍 International payment / PayPal USD</strong><p id="paypalPrice" style="margin:8px 0">PayPal checkout not configured</p><button type="button" id="paypalPay" disabled>Pay with PayPal (USD)</button><button type="button" id="paypalConfirm" hidden>Verify PayPal payment</button><p id="paypalMessage" aria-live="polite"></p>';
 $('pixRestore').parentElement.append(paypalPanel);
 const paypalPay=paypalPanel.querySelector('#paypalPay'),paypalConfirm=paypalPanel.querySelector('#paypalConfirm'),paypalMessage=paypalPanel.querySelector('#paypalMessage');
 const paypalRequest=async(path,data)=>{const response=await fetch('/api/paypal/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const json=await response.json();if(!response.ok)throw Error(json.error||'PayPal unavailable');return json};
 const paypalStore='bordai-paypal-order-v1';
 paypalPay.onclick=async()=>{if(!quote||!unchanged())return;paypalPay.disabled=true;try{const result=await paypalRequest('create',{quoteToken:quote.quoteToken});paypalAccess=result.accessToken;localStorage.setItem(paypalStore,JSON.stringify({accessToken:paypalAccess,hash:quote.hash}));location.assign(result.approvalUrl)}catch(e){paypalMessage.textContent=e.message;paypalPay.disabled=false}};
 paypalConfirm.onclick=async()=>{if(!paypalAccess)return;paypalConfirm.disabled=true;try{const result=await paypalRequest('confirm',{accessToken:paypalAccess});paypalPaid=result.paid===true;paypalMessage.textContent=paypalPaid?'PayPal payment confirmed. PES and DST unlocked.':'PayPal payment not completed yet.';refreshReview()}catch(e){paypalMessage.textContent=e.message}finally{paypalConfirm.disabled=false}};
 const controls=adminPanel.querySelector('#adminControls'),adminPassword=adminPanel.querySelector('#adminPassword'),adminMessage=adminPanel.querySelector('#adminMessage'),adminLogin=adminPanel.querySelector('#adminLogin'),adminLogout=adminPanel.querySelector('#adminLogout');
 adminPanel.querySelector('#adminToggle').onclick=()=>{controls.hidden=!controls.hidden};
 function renderAdmin(){adminPassword.hidden=admin;adminLogin.hidden=admin;adminLogout.hidden=!admin;adminMessage.textContent=admin?'Administrador autenticado: downloads gratuitos liberados.':'';refreshReview()}
 adminLogin.onclick=async()=>{adminLogin.disabled=true;try{const result=await request('admin/login',{email:adminPanel.querySelector('#adminEmail').value.trim().toLowerCase(),password:adminPassword.value});adminPassword.value='';admin=result.authenticated===true;renderAdmin()}catch(e){adminMessage.textContent=e.message}finally{adminLogin.disabled=false}};
 adminLogout.onclick=async()=>{try{await request('admin/logout',{});admin=false;renderAdmin()}catch(e){adminMessage.textContent=e.message}};
 async function refreshAdmin(){try{admin=(await request('admin/status',{})).authenticated===true}catch{admin=false}renderAdmin()}
 function refreshReview(){const allowed=canExport();$('pixPay').disabled=busy||!allowed||!quote?.enabled||paid||!!order;$('pixCheck').disabled=busy||!order;for(const [id,ext]of [['exportPES','pes'],['exportDST','dst']]){$(id).disabled=!allowed||(!paid&&!admin&&!paypalPaid);$(id).onclick=()=>download(ext)}}
 function showOrder(){if(!order)return;$('pixQR').hidden=false;$('pixQRImage').src='data:image/png;base64,'+order.qrImage;$('pixPayload').value=order.payload;$('pixValidity').textContent='Pix válido até '+new Date(order.expiresAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})+'.';$('pixReceipt').hidden=false;refreshReview();}
 async function check(automatic=false){if(!order||busy)return;stop();busy=true;refreshReview();try{const status=await request('status',{orderToken:order.orderToken});if(status.hash!==quote?.hash||status.amount!==quote?.amount)throw Error('Este pedido não corresponde à matriz atual.');order={...order,...status};remember();paid=status.paid===true;if(paid){stop();message('Pagamento confirmado. PES e DST liberados para esta versão.');$('pixQR').hidden=true;}else{showOrder();message(Date.now()>order.expiresAt?'O prazo do QR Code terminou. Se você pagou, use Verificar pagamento. Não pague novamente antes de conferir.':'Aguardando confirmação do Pix. A liberação é automática.');if(Date.now()<order.expiresAt&&$('exportDialog').open)timer=setTimeout(()=>check(true),12000)}}catch(e){message(e.message)}finally{busy=false;refreshReview()}}
 async function open(){stop();paypalPaid=false;paypalAccess=null;paypalConfirm.hidden=true;paypalPay.disabled=true;const seq=++sequence;quote=null;order=null;paid=false;busy=true;$('pixQR').hidden=true;$('pixReceipt').hidden=true;const p=getPattern(),input=inputNow();snapshot=JSON.stringify(input);$('pixPrice').textContent=money(Math.ceil(p.metrics.stitches/1000)*100);$('pixBreakdown').textContent=p.metrics.stitches.toLocaleString('pt-BR')+' pontos · valor previsto';message('Conferindo os pontos e o valor final…');refreshReview();try{if(!p.metrics.stitches){message('Adicione pontos à matriz antes de exportar.');$('pixPrice').textContent='—';return}const raw=new TextEncoder().encode(JSON.stringify(input));if(crypto.subtle){currentKey=[...new Uint8Array(await crypto.subtle.digest('SHA-256',raw))].map(x=>x.toString(16).padStart(2,'0')).join('')}else{let h=2166136261;for(const b of raw){h=Math.imul(h^b,16777619)}currentKey='cache-'+(h>>>0).toString(16)+'-'+raw.length}const result=await request('quote',input);if(seq!==sequence)return;quote=result;
 try{const saved=JSON.parse(localStorage.getItem(paypalStore)||'null');if(saved?.hash===quote.hash&&typeof saved.accessToken==='string'){paypalAccess=saved.accessToken;paypalConfirm.hidden=false;paypalMessage.textContent='Return from PayPal? Click Verify PayPal payment.';}}catch{}
 try{const config=await fetch('/api/paypal/config').then(r=>r.json());paypalRate=config.enabled?config.rate:null;paypalPay.disabled=!config.enabled;paypalPanel.querySelector('#paypalPrice').textContent=config.enabled?'USD '+(Math.ceil(quote.stitches/1000)*paypalRate/100).toFixed(2)+' · '+(config.sandbox?'Sandbox test':'Live PayPal'):'PayPal USD will be available after merchant setup.';}catch{paypalRate=null;paypalPay.disabled=true;}
 $('pixPrice').textContent=money(quote.amount);$('pixBreakdown').textContent=quote.stitches.toLocaleString('pt-BR')+' pontos · '+Math.ceil(quote.stitches/1000)+' blocos de 1.000';try{order=JSON.parse(localStorage.getItem(storageKey())||sessionStorage.getItem(storageKey())||'null');if(order?.hash!==quote.hash)order=null}catch{order=null}message(quote.enabled?'Crie o Pix para liberar os dois formatos. Não é necessário criar conta.':'Pagamento Pix temporariamente indisponível. Nenhuma cobrança será gerada.');await refreshAdmin();if(order){busy=false;await check(true)}}catch(e){if(seq===sequence)message(e.message)}finally{if(seq===sequence){busy=false;refreshReview()}}}
 async function pay(){if(!unchanged()){message('O desenho mudou. Feche e abra a exportação para conferir a nova versão.');return}if(busy||!quote?.enabled||!canExport()||order)return;busy=true;refreshReview();message('Gerando seu Pix…');try{order=await request('create',{quoteToken:quote.quoteToken});remember();showOrder();message('Escaneie o QR Code ou use Pix Copia e Cola.');busy=false;await check(true)}catch(e){message(e.message)}finally{busy=false;refreshReview()}}
 async function download(format){if(!unchanged()){message('O desenho mudou. Abra a versão original deste projeto para baixar a compra.');return}if((!paid&&!admin&&!paypalPaid)||(!admin&&!order&&!paypalAccess)||!canExport()||!quote)return;const b=$(format==='pes'?'exportPES':'exportDST');b.disabled=true;try{const viaPaypal=!admin&&!paid&&paypalPaid;const response=await fetch(admin?'/api/pix/admin/download':viaPaypal?'/api/paypal/download':'/api/pix/download',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(admin?{quoteToken:quote.quoteToken,format}:viaPaypal?{accessToken:paypalAccess,format}:{orderToken:order.orderToken,format})});if(!response.ok){const data=await response.json();throw Error(data.error||'Pagamento não confirmado.')}const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=((admin||paypalPaid?quote.name:order.name)||'Bordado')+'.'+format;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);message(admin?'Download administrativo concluído.':'Arquivo liberado. Baixar novamente esta versão não gera nova cobrança.')}catch(e){message(e.message)}finally{refreshReview()}}
 $('pixPay').onclick=pay;$('pixCheck').onclick=()=>check(false);$('pixCopy').onclick=async()=>{try{await navigator.clipboard.writeText(order.payload);message('Código Pix copiado. Cole no aplicativo do seu banco.')}catch{message('Selecione o código abaixo e copie para pagar no seu banco.')}};
 $('pixReceipt').onclick=()=>{if(!order)return;const blob=new Blob([JSON.stringify({type:'bordai-pix-access-v1',order},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='BordAI-acesso-Pix.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);message('Guarde este arquivo de acesso. Ele não contém sua senha nem dados bancários.');};
 $('pixRestore').onclick=()=>$('pixAccessFile').click();$('pixAccessFile').onchange=async()=>{try{const file=$('pixAccessFile').files[0];if(!file||file.size>8000000)throw Error('Arquivo de acesso inválido.');const saved=JSON.parse(await file.text());if(saved.type!=='bordai-pix-access-v1'||saved.order?.hash!==quote?.hash||typeof saved.order?.orderToken!=='string')throw Error('Este acesso não corresponde à matriz atual. Abra a mesma versão do projeto e tente novamente.');order=saved.order;await check(true)}catch(e){message(e.message)}finally{$('pixAccessFile').value=''}};
 $('exportDialog').addEventListener('close',()=>{stop();sequence++});return {open,refreshReview};
}
